#include <psre/m040/controls.h>
#include <psre/m034/window.h>
#include <psre/m032/graphics.h>
#include <psre/m033/font.h>
#include <psre/m030/input.h>
#include <psre/serial.h>
#include <stddef.h>

typedef struct { bool used,open,selection_changed; psre_m038_container_id_t container; psre_m040_type_t type; int32_t x,y,w,h,value,min,max,scroll; uint8_t count; char title[PSRE_M040_TEXT_CAPACITY]; char items[PSRE_M040_MAX_ITEMS][PSRE_M040_TEXT_CAPACITY]; char cells[PSRE_M040_MAX_ITEMS][3][PSRE_M040_TEXT_CAPACITY]; } control_t;
static control_t controls[PSRE_M040_MAX_CONTROLS]; static psre_m040_status_t status;
static char modal_title[PSRE_M040_TEXT_CAPACITY],modal_message[PSRE_M040_TEXT_CAPACITY];
static void cp(char*d,const char*s){uint32_t i=0;while(s&&s[i]&&i+1<PSRE_M040_TEXT_CAPACITY){d[i]=s[i];++i;}d[i]=0;}
static psre_m032_color_t rgb(uint8_t r,uint8_t g,uint8_t b){psre_m032_color_t c={r,g,b};return c;}
static control_t *get(psre_m040_control_id_t id){return status.initialized&&id<PSRE_M040_MAX_CONTROLS&&controls[id].used?&controls[id]:0;}
static bool origin(control_t*c,int32_t*ox,int32_t*oy){psre_m038_container_info_t ci;psre_m034_window_info_t wi;if(!c||!psre_m038_get_container(c->container,&ci)||!psre_m034_get_window(ci.window,&wi)||!wi.visible)return false;*ox=wi.x+2;*oy=wi.y+24;return true;}
bool psre_m040_initialize(void){for(uint8_t i=0;i<PSRE_M040_MAX_CONTROLS;++i)controls[i]=(control_t){0};status=(psre_m040_status_t){.initialized=true};modal_title[0]=modal_message[0]=0;return true;}
void psre_m040_reset(void){(void)psre_m040_initialize();}
psre_m040_control_id_t psre_m040_create(psre_m038_container_id_t c,psre_m040_type_t t,const char*title,int32_t x,int32_t y,int32_t w,int32_t h){if(!status.initialized||t>PSRE_M040_SLIDER||!title||x<0||y<0||w<24||h<16){++status.errors;return PSRE_M040_INVALID_CONTROL;}psre_m038_container_info_t ci;psre_m034_window_info_t wi;if(!psre_m038_get_container(c,&ci)||!psre_m034_get_window(ci.window,&wi)||x+w>wi.width-4||y+h>wi.height-26){++status.errors;return PSRE_M040_INVALID_CONTROL;}for(uint8_t i=0;i<PSRE_M040_MAX_CONTROLS;++i)if(!controls[i].used){controls[i]=(control_t){.used=true,.container=c,.type=t,.x=x,.y=y,.w=w,.h=h,.max=100};cp(controls[i].title,title);++status.control_count;return i;}++status.errors;return PSRE_M040_INVALID_CONTROL;}
bool psre_m040_add_item(psre_m040_control_id_t id,const char*s){control_t*c=get(id);if(!c||!s||c->count>=PSRE_M040_MAX_ITEMS||(c->type!=PSRE_M040_COMBO&&c->type!=PSRE_M040_LIST&&c->type!=PSRE_M040_RADIO_GROUP)){if(status.initialized)++status.errors;return false;}cp(c->items[c->count++],s);return true;}
bool psre_m040_set_value(psre_m040_control_id_t id,int32_t v){control_t*c=get(id);if(!c)return false;if(c->type==PSRE_M040_PROGRESS||c->type==PSRE_M040_SLIDER||c->type==PSRE_M040_SCROLLBAR){if(v<c->min)v=c->min;if(v>c->max)v=c->max;}else if(c->type==PSRE_M040_COMBO||c->type==PSRE_M040_LIST||c->type==PSRE_M040_RADIO_GROUP){if(v<0||v>=c->count)return false;}c->value=v;++status.changes;return true;}
bool psre_m040_get_value(psre_m040_control_id_t id,int32_t*v){control_t*c=get(id);if(!c||!v)return false;*v=c->value;return true;}
bool psre_m040_set_range(psre_m040_control_id_t id,int32_t lo,int32_t hi){control_t*c=get(id);if(!c||lo>=hi||(c->type!=PSRE_M040_PROGRESS&&c->type!=PSRE_M040_SLIDER&&c->type!=PSRE_M040_SCROLLBAR))return false;c->min=lo;c->max=hi;if(c->value<lo)c->value=lo;if(c->value>hi)c->value=hi;return true;}
bool psre_m040_set_table_cell(psre_m040_control_id_t id,uint8_t row,uint8_t col,const char*s){control_t*c=get(id);if(!c||c->type!=PSRE_M040_TABLE||row>=PSRE_M040_MAX_ITEMS||col>=3||!s)return false;cp(c->cells[row][col],s);if(c->count<=row)c->count=row+1;return true;}
bool psre_m040_clear_table(psre_m040_control_id_t id){control_t*c=get(id);if(!c||c->type!=PSRE_M040_TABLE)return false;c->count=0;c->value=-1;c->selection_changed=false;for(uint8_t r=0;r<PSRE_M040_MAX_ITEMS;++r)for(uint8_t col=0;col<3;++col)c->cells[r][col][0]=0;return true;}
bool psre_m040_get_table_selection(psre_m040_control_id_t id,uint8_t*row){control_t*c=get(id);if(!c||!row||c->type!=PSRE_M040_TABLE||!c->selection_changed||c->value<0||c->value>=c->count)return false;c->selection_changed=false;*row=(uint8_t)c->value;return true;}
bool psre_m040_set_modal(bool v,const char*t,const char*m){if(!status.initialized)return false;status.modal_visible=v;if(t)cp(modal_title,t);if(m)cp(modal_message,m);return true;}
static bool text(const char*s,int32_t x,int32_t y,uint32_t w,psre_m032_color_t fg){psre_m033_text_style_t st={.x=x,.y=y,.width=w,.height=12,.font=PSRE_M033_FONT_8X8,.foreground=fg,.background={0,0,0},.opaque_background=false};return psre_m033_draw_string(s,&st);}
static bool draw(control_t*c){int32_t ox,oy;if(!origin(c,&ox,&oy))return false;int32_t x=ox+c->x,y=oy+c->y;psre_m032_color_t fg=rgb(35,45,58),edge=rgb(90,115,140),fill=rgb(245,248,251),accent=rgb(40,125,180);bool ok=true;
 ok=psre_m032_draw_rect(x,y,c->w,c->h,edge)&&ok;ok=text(c->title,x+4,y+3,(uint32_t)(c->w-8),fg)&&ok;
 if(c->type==PSRE_M040_COMBO){ok=psre_m032_fill_rect(x+3,y+18,c->w-6,c->h-21,fill)&&ok;const char*s=c->value>=0&&c->value<c->count?c->items[c->value]:"Select...";ok=text(s,x+7,y+23,(uint32_t)(c->w-28),fg)&&ok;ok=text(c->open?"^":"v",x+c->w-18,y+23,12,accent)&&ok;if(c->open)for(uint8_t i=0;i<c->count&&i<4;++i){int32_t yy=y+c->h+(int32_t)i*18;ok=psre_m032_fill_rect(x+3,yy,c->w-6,18,fill)&&ok;ok=text(c->items[i],x+7,yy+4,(uint32_t)(c->w-12),fg)&&ok;}}
 else if(c->type==PSRE_M040_LIST||c->type==PSRE_M040_RADIO_GROUP){for(uint8_t i=0;i<c->count;++i){int32_t yy=y+18+(int32_t)i*18;if(yy+16>y+c->h)break;if(c->value==i)ok=psre_m032_fill_rect(x+2,yy,c->w-4,17,rgb(210,230,244))&&ok;ok=text(c->type==PSRE_M040_RADIO_GROUP?(c->value==i?"(o)":"( )"):"",x+5,yy+3,26,accent)&&ok;ok=text(c->items[i],x+30,yy+3,(uint32_t)(c->w-34),fg)&&ok;}}
 else if(c->type==PSRE_M040_TABLE){for(uint8_t r=0;r<c->count;++r){int32_t yy=y+18+(int32_t)r*18;if(yy+17>y+c->h)break;for(uint8_t col=0;col<3;++col)ok=text(c->cells[r][col],x+4+(int32_t)col*(c->w/3),yy+3,(uint32_t)(c->w/3-4),fg)&&ok;}}
 else if(c->type==PSRE_M040_PROGRESS){int32_t bw=c->w-12;ok=psre_m032_fill_rect(x+6,y+20,bw,12,rgb(220,226,232))&&ok;int32_t span=c->max-c->min;int32_t amount=span?bw*(c->value-c->min)/span:0;if(amount>0)ok=psre_m032_fill_rect(x+6,y+20,amount,12,accent)&&ok;}
 else {int32_t track=c->w-20;ok=psre_m032_fill_rect(x+10,y+c->h/2-2,track,4,rgb(210,218,226))&&ok;int32_t span=c->max-c->min;int32_t pos=span?track*(c->value-c->min)/span:0;ok=psre_m032_fill_circle(x+10+pos,y+c->h/2,5,accent)&&ok;if(c->type==PSRE_M040_SCROLLBAR)ok=text("Scroll",x+4,y+3,(uint32_t)(c->w-8),fg)&&ok;}
 return ok;}
bool psre_m040_render_container(psre_m038_container_id_t id){if(!status.initialized)return false;bool ok=true;for(uint8_t i=0;i<PSRE_M040_MAX_CONTROLS;++i)if(controls[i].used&&controls[i].container==id)ok=draw(&controls[i])&&ok;++status.redraws;return ok;}
bool psre_m040_render(void){if(!status.initialized)return false;bool ok=true;for(uint8_t i=0;i<PSRE_M040_MAX_CONTROLS;++i)if(controls[i].used)ok=draw(&controls[i])&&ok;if(status.modal_visible){ok=psre_m032_fill_rect(20,20,440,150,rgb(22,37,55))&&ok;ok=psre_m032_draw_rect(20,20,440,150,rgb(90,150,190))&&ok;ok=text(modal_title,34,34,400,rgb(245,248,252))&&ok;ok=text(modal_message,34,62,410,rgb(225,232,240))&&ok;ok=text("Press Enter or Escape to close",34,130,400,rgb(180,205,225))&&ok;}++status.redraws;return ok;}
bool psre_m040_handle_event(const psre_input_event_t*e){if(!status.initialized||!e)return false;++status.events;if(status.modal_visible){if(e->type==PSRE_INPUT_KEY_DOWN&&(e->code==0x28||e->code==0x29||e->character=='\n'||e->character==27)){status.modal_visible=false;return true;}if(e->type==PSRE_INPUT_MOUSE_BUTTON_DOWN){status.modal_visible=false;return true;}return true;}if(e->type!=PSRE_INPUT_MOUSE_BUTTON_DOWN)return false;for(int i=(int)PSRE_M040_MAX_CONTROLS-1;i>=0;--i){control_t*c=&controls[i];int32_t ox,oy;if(!c->used||!origin(c,&ox,&oy))continue;const psre_m030_status_t *in=psre_m030_get_status();int32_t x=ox+c->x,y=oy+c->y,mx=in?in->mouse_x:e->delta_x,my=in?in->mouse_y:e->delta_y;if(mx<x||my<y||mx>=x+c->w||my>=y+c->h+((c->open&&c->type==PSRE_M040_COMBO)?(int32_t)c->count*18:0))continue;if(c->type==PSRE_M040_COMBO){if(c->open&&my>=y+c->h){int32_t row=(my-y-c->h)/18;if(row<c->count)c->value=row;c->open=false;}else c->open=!c->open;}else if(c->type==PSRE_M040_LIST||c->type==PSRE_M040_RADIO_GROUP){int32_t row=(my-y-18)/18;if(row>=0&&row<c->count)c->value=row; }else if(c->type==PSRE_M040_TABLE){
 int32_t row=(my-y-18)/18;
 if(row>=0&&row<c->count){c->value=row;c->selection_changed=true;}
 else continue;
 }else if(c->type==PSRE_M040_SLIDER||c->type==PSRE_M040_SCROLLBAR){int32_t track=c->w-20,pos=mx-(x+10);if(pos<0)pos=0;if(pos>track)pos=track;c->value=c->min+(c->max-c->min)*pos/(track?track:1);}++status.changes;return true;}return false;}
const psre_m040_status_t*psre_m040_get_status(void){return &status;}
void psre_m040_report(void){serial_write("[M040] Advanced GUI controls ready\n");}
